from pathlib import Path
from html import escape
from build_guides import USER
root=Path(__file__).resolve().parents[1]
help=root/'help';(help/'assets').mkdir(parents=True,exist_ok=True)
nav=''.join(f'<a href="#section{i}">{escape(title)}</a>' for i,(title,_) in enumerate(USER))
articles=''.join(f'<article id="section{i}"><h2>{escape(title)}</h2>'+''.join(f'<h3>{escape(sub)}</h3><p>{escape(body)}</p>' for sub,body in paragraphs)+'</article>' for i,(title,paragraphs) in enumerate(USER))
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Carillon Bells 9.0 Help</title><link rel="stylesheet" href="assets/help.css"></head><body><aside><h1 class="notranslate" translate="no">Carillon Bells 9.0</h1><p>Portable desktop help</p><label>Search help <input id="search" type="search"></label><nav>'''+nav+'''<a href="glossary.html">Glossary</a><a href="keyword-index.html">Keyword index</a></nav><button onclick="window.print()">Print manual</button></aside><main><h1>Westminster Chimes and Carillon Bells User Help</h1><p>Last changed November 21, 2026. This manual opens locally without an internet connection. Internet access is needed for automatic translation.</p>'''+articles+'''</main><div class="gtranslate_wrapper"></div><script>document.getElementById('search').addEventListener('input',function(){const query=this.value.toLowerCase();document.querySelectorAll('article').forEach(article=>article.hidden=!article.textContent.toLowerCase().includes(query));});window.gtranslateSettings={default_language:'en',languages:['en','es','fr','de','it','pt','pl','nl','uk','ar','zh-CN','ja','ko','vi','hi','tl'],wrapper_selector:'.gtranslate_wrapper',switcher_horizontal_position:'right',switcher_vertical_position:'bottom',float_switcher_open_direction:'top'};</script><script src="https://cdn.gtranslate.net/widgets/latest/float.js" defer></script><script src="assets/translation-selector.js" defer></script></body></html>'''
for product in ('Westminster Chimes and Carillon Bells','Carillon Bells 9.0','SQLite','NLayer','WPF'):
    # Protect product terms in prose without touching script/style markup.
    marker=escape(product)
    articles=articles.replace(marker,f'<span class="notranslate" translate="no">{marker}</span>')
start=page.index('<article');end=page.index('</main>');page=page[:start]+articles+page[end:]
(help/'index.html').write_text(page,encoding='utf-8')
glossary={'Occurrence':'One scheduled song record at a specific local date and time.','Playlist key':'The pair of playlist name and song path identifying a record.','Weekly silence':'A reusable time window associated with starting weekdays.','Legacy silence':'The separate liturgical and one-off funeral silence settings.','Random directory slot':'An annual directory choice; slot 1 is fallback and slots 2–7 are overrides.','Evaluation mode':'A launch mode that suppresses automatic email while retaining actual scheduling and playback.','Portable base':'The directory containing the executable.','STARTTLS':'An explicit upgrade of an SMTP connection to TLS before authentication.','SQLite':'The embedded database engine used by Carillon.'}
for filename,title,content in [('glossary.html','Glossary',''.join('<dt>'+escape(k)+'</dt><dd>'+escape(v)+'</dd>' for k,v in glossary.items())),('keyword-index.html','Keyword index',''.join('<p><a href="index.html#section'+str(i)+'">'+escape(sub)+'</a></p>' for i,(_,parts) in enumerate(USER) for sub,_ in parts))]:
    translation='''<div class="gtranslate_wrapper"></div><script>window.gtranslateSettings={default_language:'en',languages:['en','es','fr','de','it','pt','pl','nl','uk','ar','zh-CN','ja','ko','vi','hi','tl'],wrapper_selector:'.gtranslate_wrapper',switcher_horizontal_position:'right',switcher_vertical_position:'bottom',float_switcher_open_direction:'top'};</script><script src="https://cdn.gtranslate.net/widgets/latest/float.js" defer></script><script src="assets/translation-selector.js" defer></script>'''
    content=content.replace('SQLite','<span class="notranslate" translate="no">SQLite</span>')
    (help/filename).write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>'+title+'</title><link rel="stylesheet" href="assets/help.css"><body><main><a href="index.html">Back to help</a><h1>'+title+'</h1><dl>'+content+'</dl></main>'+translation+'</body></html>',encoding='utf-8')
print('Local searchable help, print styles, glossary, keyword index and translation support created.')
